import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadUdhwaData(){const e=readFileSync(resolve(__dirname,"../../frontend/udhwa-wetlands-explorer/udhwa-data.js"),"utf-8");return new Function(e+"\nreturn { UDHWA_INFO, ECOLOGY_HYDROLOGY, BIRD_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Udhwa Wetlands Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadUdhwaData()}),describe("UDHWA_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.UDHWA_INFO.id).toBe("udhwa-wetlands"),expect(e.UDHWA_INFO.name).toContain("Udhwa"),expect(e.UDHWA_INFO.ramsarYear).toBe(2024),expect(e.UDHWA_INFO.ramsarSiteNo).toBe(2510),expect(e.UDHWA_INFO.state).toBe("Jharkhand")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.UDHWA_INFO.quickStats)).toBe(!0),expect(e.UDHWA_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, lakes hydrology, biodiversity, and conservation status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.lakesHydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.biodiversity).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("BIRD_SPECIES catalog",()=>{it("is a non-empty array of migratory bird species",()=>{expect(Array.isArray(e.BIRD_SPECIES)).toBe(!0),expect(e.BIRD_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Tufted Duck and Northern Pintail",()=>{const t=e.BIRD_SPECIES.find(e=>"tufted-duck"===e.id),a=e.BIRD_SPECIES.find(e=>"northern-pintail"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"udhwa-wetlands"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../udhwa-wetlands-explorer/index.html")})})});